path_c3 = Line:new{p0=p003, p1=p005}

-- blocks
blocks = {}
-- block blk2
surf_blk2 = CoonsPatch:new{north=path_c5, east=SubRangedPath:new{underlying_path=path_c2, t0=0.0, t1=0.012979341055999996}, south=path_c1, west=SubRangedPath:new{underlying_path=path_c4, t0=1.0, t1=0.9870206589439999}}
grid_blk2 = StructuredGrid:new{psurface=surf_blk2, niv=23, njv=11, cfList={east=growthCluster(1.2, 10, false), west=growthCluster(1.2000000000000002, 10, false)}, label="blk2"}
blocks[#blocks+1] = {grid=grid_blk2, tag="blk2", fsTag="initial", bcTags={south="wall"}}

-- block blk3
surf_blk3 = CoonsPatch:new{north=ReversedPath:new{underlying_path=path_c3}, east=SubRangedPath:new{underlying_path=path_c2, t0=0.012979341055999996, t1=1.0}, south=path_c5, west=SubRangedPath:new{underlying_path=path_c4, t0=0.9870206589439999, t1=0.0}}
grid_blk3 = StructuredGrid:new{psurface=surf_blk3, niv=23, njv=5, label="blk3"}
blocks[#blocks+1] = {grid=grid_blk3, tag="blk3", fsTag="initial", bcTags={}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   connectGrids(ids[1], "north", ids[2], "south")
